	defer C.free(unsafe.Pointer(errC))

	switch C.DeleteCredential(reasonC, idC, &errC) {
	case 0: // aka success
		return nil
	case errSecItemNotFound:
		return ErrCredentialNotFound
	default:
		errMsg := C.GoString(errC)
		return errors.New(errMsg)
	}
}

